#include <bits/stdc++.h>
using namespace std;
static const int mod=998244353;
static int dpa[5005], dpb[5005], dl[5005], dr[5005];
int main() {
	// your code goes here
	int t; 
	scanf("%d", &t);
	while(t--){
	    int n;
	    scanf("%d",&n);
	    vector<vector<int>> byte(n+1);
	    for(int i=1; i<=n; i++){
	        int x; 
	        scanf("%d",&x);
	        byte[x].push_back(i);
	    }
	    int *dp=dpa, *nw=dpb; 
	    dp[0]=1;
	    bool dee=false; 
	    
	    for(int v=1; v<=n;v++){
	        int m=byte[v].size();
	        int capp=v-1;
	        for (int x=0;x<=v;x++){
	            nw[x]=0;
	        }
	        if (m){
	            for(int x=0;x<=v;x++) dl[x]=dr[x]=0;
	            int *dd[2]={dl,dr};
	            for (int i :byte[v]){
	                int q=(i+1)>>1, b=n-(i>>1);
	                int c=(n+2-i)>>1, a=(n+i)>>1;
	                int fs[2], fl[2],fh[2],fc=0;
	                int gs[2],gl[2],gh[2],gc=0;
	                if(v<b){
	                    fs[fc]=0;
	                    fl[fc]=q-1;
	                    fh[fc]=q-1;
	                    fc++;
	                }
	                else if (v==b){
	                    fs[fc]=0; fl[fc]=0; fh[fc]=q-1; fc++; 
	                    fs[fc]=1; fl[fc]=0; fh[fc]=q-1; fc++;
	                }
	                if(v<a){
	                    gs[gc]=1; gl[gc]=v-c; gh[gc]=v-c; gc++;
	                }
	                else if (v==a){
	                    gs[gc]=0; gl[gc]=v-c; gh[gc]=capp; gc++; 
	                    gs[gc]=1, gl[gc]=v-c; gh[gc]= capp; gc++;
	                }
	                
	                auto add =[&](int s, int lo, int hi, int val){
	                    lo=max(lo,0); hi=min(hi,capp);
	                    if (lo<=hi){
	                        dd[s][lo]+=val; dd[s][hi+1]-=val;
	                    }
	                };
	                for(int k=0;k<fc;k++) add(fs[k],fl[k],fh[k],1);
	                for(int k=0;k<gc;k++) add(gs[k],gl[k],gh[k],1);
	                for(int k=0;k<fc;k++){
	                    for(int j=0;j<gc;j++){
	                        if(fs[k]==gs[j]) add(fs[k],max(fl[k],gl[j]), min(fh[k],gh[j]),-1);
	                    }
	                }
	                
	            }
	            int cl=0, cr=0;
	            for(int x=0; x<v;x++){
	                cl+=dl[x]; cr+=dr[x];
	                int d=dp[x];
	                if (!d) continue; 
	                if(v<n && cr==m){
	                    nw[x]+=d; if (nw[x]>=mod ) nw[x]-=mod;
	                }
	                if(cl==m){
	                    nw[x+1]+=d; if (nw[x+1]>=mod) nw[x+1]-=mod;
	                }
	            }
	        }
	            else{
	                for(int x=0;x<v;x++){
	                    int d=dp[x];
	                    if(v<n){
	                        nw[x]+=d; if (nw[x]>=mod) nw[x]-=mod;
	                    }
	                    nw[x+1]+=d; if(nw[x+1]>=mod) nw[x+1]-=mod;
	                }
	            }
	            swap(dp,nw);
	            bool f=false;
	            for(int x=0;x<=v;x++) if (dp[x]) { f=true; break;} 
	            if(!f) {dee =true; break;}
	            
	        }
	        long long ans=0;
	        if(!dee) for (int x=0; x<=n; x++) ans+=dp[x];
	        printf("%lld\n", ans%mod);
	    }
	    
	
	

}
